    p_sk_propose.add_argument(
        "--dry-run", action="store_true", dest="dry_run",
        help="rank candidate clusters (member ids + scores) WITHOUT emitting")
    p_sk_propose.set_defaults(func=cmd_skill_propose)

    # update -----------------------------------------------------------------
